const canvas=$('#space-game'),ctx=canvas.getContext('2d'),W=720,H=660;let running=false,paused=false,score=0,wave=1,lives=3,best=Number(read('te-space-best-v1',0))||0,ship={x:360,y:590},shots=[],enemies=[],enemyShots=[],particles=[],keys=new Set(),clock=0,shotClock=0,enemyClock=0,invincible=0,shield=0,last=0,raf=0,dragging=false;
